// ядро/ports        — ядро описывает, что ему нужно
interface Orders {
  save(order: Order): Promise<void>
  byId(id: OrderId): Promise<Order | null>
}

// ядро/place-order  — сценарий знает только порт
function makePlaceOrder(orders: Orders) {
  return async (input) => {
    order = Order.create(input)      // правила домена
    await orders.save(order)
    return order
  }
}

